// n8n Code node — "Run Once for All Items" mode mein set karo

const universityPatterns = [
  { name: "University of the Punjab", regex: /UNIVERSITY OF THE PUNJAB/i },
  { name: "Government College University Lahore", regex: /GOVERNMENT COLLEGE UNIVERSITY/i },
  { name: "University of Engineering and Technology Lahore", regex: /UNIVERSITY OF ENGINEERING AND TECHNOLOGY/i },
  { name: "University of Sargodha", regex: /UNIVERSITY OF SARGODHA/i },
  { name: "Quaid-i-Azam University", regex: /QUAID-I-AZAM UNIVERSITY/i },
  { name: "University of Peshawar", regex: /UNIVERSITY OF PESHAWAR/i },
  { name: "University of Agriculture, Faisalabad", regex: /AGRICULTURE,?\s*FAISALABAD/i },
  // yahan aur universities add karte jao jitni PDF mein hain
];

let currentUniversity = "Unknown";
const output = [];

for (const item of $input.all()) {
  const text = item.json.text || item.json.pageContent || "";

  // Check if this chunk contains a new university header
  for (const uni of universityPatterns) {
    if (uni.regex.test(text)) {
      currentUniversity = uni.name;
      break; // pehla match le lo, chunk mein header hoga to shuru mein hi hoga
    }
  }

  // Tag this chunk with currentUniversity (carry-forward)
  item.json.metadata = {
    ...(item.json.metadata || {}),
    university: currentUniversity
  };

  output.push(item);
}

return output;

// n8n Code node — "Run Once for Each Item" mode mein set karo
// Ye node user ke question se university ka naam detect karta hai

const universityPatterns = [
  { name: "University of the Punjab", keywords: ["punjab university", "university of the punjab", "pu lahore"] },
  { name: "Government College University Lahore", keywords: ["gcu", "government college university"] },
  { name: "University of Engineering and Technology Lahore", keywords: ["uet", "engineering and technology"] },
  { name: "University of Sargodha", keywords: ["sargodha"] },
  { name: "Quaid-i-Azam University", keywords: ["quaid-i-azam", "quaid e azam", "qau"] },
  { name: "University of Peshawar", keywords: ["peshawar"] },
  { name: "University of Agriculture, Faisalabad", keywords: ["agriculture", "faisalabad", "uaf"] },
  // yahan aur universities add karte jao
];

// Aapke chat input field ka naam yahan check kar lena (chatInput ya question)
const question = ($json.chatInput || $json.question || $json.text || "").toLowerCase();

let detected = null;
for (const uni of universityPatterns) {
  for (const kw of uni.keywords) {
    if (question.includes(kw)) {
      detected = uni.name;
      break;
    }
  }
  if (detected) break;
}

return {
  ...$json,
  detectedUniversity: detected // null agar koi university naam question mein nahi mila
};
